import React, { useState, useEffect } from 'react';
import { documentService } from '../../services/documentService';
import { clientService } from '../../services/clientService';
import { useAuth } from '../../contexts/AuthContext';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import {
  Folder,
  FolderPlus,
  Upload,
  Search,
  ChevronRight,
  Home,
  Download,
  Trash2,
  FileText,
  MoreVertical,
} from 'lucide-react';
import Swal from 'sweetalert2';
import { UploadDocumentModalImproved } from './UploadDocumentModalImproved';

export const DocumentManager = ({ onUploadSuccess }) => {
  const { user } = useAuth();
  const [clients, setClients] = useState([]);
  const [selectedClient, setSelectedClient] = useState(null);
  const [folders, setFolders] = useState([]);
  const [documents, setDocuments] = useState([]);
  const [currentPath, setCurrentPath] = useState([]);
  const [currentFolderId, setCurrentFolderId] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [showUploadModal, setShowUploadModal] = useState(false);

  // Cargar clientes
  useEffect(() => {
    loadClients();
  }, []);

  // Cargar carpetas y documentos cuando cambia cliente o carpeta
  useEffect(() => {
    if (selectedClient) {
      loadFolders();
      loadDocuments();
    }
  }, [selectedClient, currentFolderId]);

  const loadClients = async () => {
    try {
      let data = [];
      
      // Si es consultor, cargar solo sus clientes asignados
      if (user?.role === 'user') {
        const ClientTeam = require('../../services/clientTeamService').clientTeamService;
        const assignments = await ClientTeam.getConsultantClients(user._id);
        data = assignments.map(a => a.client_id);
      } else {
        // Admin y super admin ven todos
        data = await clientService.getAll();
      }
      
      setClients(data);
    } catch (error) {
      console.error('Error loading clients:', error);
    }
  };

  const loadFolders = async () => {
    try {
      const data = await documentService.getFolders(selectedClient, currentFolderId);
      setFolders(data);
    } catch (error) {
      console.error('Error loading folders:', error);
    }
  };

  const loadDocuments = async () => {
    try {
      setLoading(true);
      const data = await documentService.getAll({
        client_id: selectedClient,
        folder_id: currentFolderId,
        search: searchTerm,
      });
      setDocuments(data);
    } catch (error) {
      console.error('Error loading documents:', error);
    } finally {
      setLoading(false);
    }
  };

  // Búsqueda con debounce
  useEffect(() => {
    const timer = setTimeout(() => {
      loadDocuments();
    }, 500);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  const handleCreateFolder = async () => {
    const { value: folderName } = await Swal.fire({
      title: 'Nueva Carpeta',
      input: 'text',
      inputLabel: 'Nombre de la carpeta',
      inputPlaceholder: 'Ej: Auditorías, Certificaciones, etc.',
      showCancelButton: true,
      confirmButtonColor: '#16a34a',
      inputValidator: (value) => {
        if (!value) return 'El nombre es requerido';
      },
    });

    if (folderName) {
      try {
        await documentService.createFolder({
          name: folderName,
          client_id: selectedClient,
          parent_folder_id: currentFolderId,
        });
        loadFolders();
        Swal.fire({
          icon: 'success',
          title: 'Carpeta creada',
          toast: true,
          position: 'top-end',
          showConfirmButton: false,
          timer: 2000,
        });
      } catch (error) {
        Swal.fire('Error', 'Error al crear carpeta', 'error');
      }
    }
  };

  const handleNavigateFolder = (folder) => {
    setCurrentFolderId(folder._id);
    setCurrentPath([...currentPath, folder]);
  };

  const handleBreadcrumb = (index) => {
    if (index === -1) {
      setCurrentFolderId(null);
      setCurrentPath([]);
    } else {
      setCurrentFolderId(currentPath[index]._id);
      setCurrentPath(currentPath.slice(0, index + 1));
    }
  };

  const handleDeleteDocument = async (docId) => {
    const result = await Swal.fire({
      title: '¿Eliminar documento?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      confirmButtonText: 'Sí, eliminar',
      cancelButtonText: 'Cancelar',
    });

    if (result.isConfirmed) {
      try {
        await documentService.delete(docId);
        loadDocuments();
        Swal.fire({
          icon: 'success',
          title: 'Documento eliminado',
          toast: true,
          position: 'top-end',
          showConfirmButton: false,
          timer: 2000,
        });
      } catch (error) {
        Swal.fire('Error', 'Error al eliminar', 'error');
      }
    }
  };

  const handleDownloadDocument = async (document) => {
    try {
      const blob = await documentService.download(document._id);
      const url = window.URL.createObjectURL(blob);
      const a = window.document.createElement('a');
      a.href = url;
      a.download = document.file_name;
      window.document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      window.document.body.removeChild(a);
    } catch (error) {
      Swal.fire('Error', 'Error al descargar documento', 'error');
    }
  };

  const handleUploadSuccess = () => {
    loadDocuments();
    setShowUploadModal(false);
    if (onUploadSuccess) onUploadSuccess();
  };

  const getSelectedClientName = () => {
    const client = clients.find(c => c._id === selectedClient);
    return client?.company_name || 'Selecciona un cliente';
  };

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Gestor de Documentos</h2>
          <p className="text-sm text-gray-600 mt-1">
            Organiza documentos por carpetas y año
          </p>
        </div>
        <Button
          onClick={() => setShowUploadModal(true)}
          className="bg-green-600 hover:bg-green-700"
          disabled={!selectedClient}
        >
          <Upload className="w-4 h-4 mr-2" />
          Subir Documento
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Sidebar */}
        <div className="lg:col-span-1 space-y-4">
          {/* Selección de Cliente */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Cliente</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {clients.length > 0 ? (
                  <select
                    value={selectedClient || ''}
                    onChange={(e) => {
                      setSelectedClient(e.target.value);
                      setCurrentFolderId(null);
                      setCurrentPath([]);
                      setSearchTerm('');
                    }}
                    className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent"
                  >
                    <option value="">-- Seleccionar cliente --</option>
                    {clients.map((client) => (
                      <option key={client._id} value={client._id}>
                        {client.company_name}
                      </option>
                    ))}
                  </select>
                ) : (
                  <p className="text-sm text-gray-500">
                    No tienes clientes asignados
                  </p>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Información */}
          {selectedClient && (
            <Card className="bg-blue-50 border-blue-200">
              <CardContent className="pt-6">
                <p className="text-sm text-blue-900">
                  <strong>Cliente activo:</strong>
                </p>
                <p className="text-sm text-blue-700 mt-1 truncate">
                  {getSelectedClientName()}
                </p>
              </CardContent>
            </Card>
          )}
        </div>

        {/* Main Content */}
        <div className="lg:col-span-3">
          {!selectedClient ? (
            <Card className="text-center py-12">
              <div className="flex flex-col items-center">
                <Folder className="w-16 h-16 text-gray-300 mb-4" />
                <p className="text-gray-500 text-lg">
                  Selecciona un cliente para comenzar
                </p>
              </div>
            </Card>
          ) : (
            <div className="space-y-4">
              {/* Búsqueda y Acciones */}
              <div className="flex flex-col sm:flex-row gap-3">
                <div className="flex-1 relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                  <Input
                    placeholder="Buscar documentos..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-10"
                  />
                </div>
                <Button
                  onClick={handleCreateFolder}
                  variant="outline"
                  className="border-blue-300 text-blue-600 hover:bg-blue-50"
                >
                  <FolderPlus className="w-4 h-4 mr-2" />
                  Nueva Carpeta
                </Button>
              </div>

              {/* Breadcrumb */}
              {currentPath.length > 0 && (
                <div className="p-3 bg-white rounded-lg border border-gray-200 flex items-center gap-2 overflow-x-auto">
                  <button
                    onClick={() => handleBreadcrumb(-1)}
                    className="flex items-center gap-1 text-green-600 hover:underline whitespace-nowrap text-sm"
                  >
                    <Home className="w-4 h-4" />
                    Inicio
                  </button>
                  {currentPath.map((folder, index) => (
                    <React.Fragment key={folder._id}>
                      <ChevronRight className="w-4 h-4 text-gray-400 flex-shrink-0" />
                      <button
                        onClick={() => handleBreadcrumb(index)}
                        className="text-green-600 hover:underline whitespace-nowrap text-sm"
                      >
                        {folder.name}
                      </button>
                    </React.Fragment>
                  ))}
                </div>
              )}

              {/* Carpetas */}
              {folders.length > 0 && (
                <div>
                  <h3 className="text-sm font-semibold text-gray-700 mb-3 uppercase tracking-wide">
                    Carpetas
                  </h3>
                  <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                    {folders.map((folder) => (
                      <div
                        key={folder._id}
                        onClick={() => handleNavigateFolder(folder)}
                        className="p-4 bg-blue-50 rounded-lg border border-blue-200 hover:border-blue-400 hover:bg-blue-100 cursor-pointer transition-all"
                      >
                        <Folder className="w-8 h-8 text-blue-500 mb-2" />
                        <p className="text-xs font-medium text-gray-900 truncate">
                          {folder.name}
                        </p>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Documentos */}
              <div>
                <h3 className="text-sm font-semibold text-gray-700 mb-3 uppercase tracking-wide">
                  Documentos
                </h3>
                {loading ? (
                  <div className="text-center py-8">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-green-500 mx-auto"></div>
                  </div>
                ) : documents.length > 0 ? (
                  <div className="space-y-2">
                    {documents.map((doc) => (
                      <div
                        key={doc._id}
                        className="p-4 bg-white rounded-lg border border-gray-200 hover:border-green-500 transition-all flex items-center justify-between group"
                      >
                        <div className="flex items-center gap-3 flex-1 min-w-0">
                          <FileText className="w-5 h-5 text-green-600 flex-shrink-0" />
                          <div className="flex-1 min-w-0">
                            <p className="font-medium text-gray-900 truncate text-sm">
                              {doc.title}
                            </p>
                            <p className="text-xs text-gray-500">
                              {doc.file_name} · {(doc.file_size / 1024 / 1024).toFixed(2)} MB
                            </p>
                          </div>
                        </div>
                        <div className="flex gap-1 ml-4 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button
                            onClick={() => handleDownloadDocument(doc)}
                            className="p-2 hover:bg-green-50 rounded text-green-600"
                            title="Descargar"
                          >
                            <Download className="w-4 h-4" />
                          </button>
                          <button
                            onClick={() => handleDeleteDocument(doc._id)}
                            className="p-2 hover:bg-red-50 rounded text-red-600"
                            title="Eliminar"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8 bg-gray-50 rounded-lg border border-dashed border-gray-300">
                    <FileText className="w-10 h-10 text-gray-300 mx-auto mb-2" />
                    <p className="text-gray-500 text-sm">
                      {searchTerm
                        ? 'No hay documentos que coincidan'
                        : 'No hay documentos en esta carpeta'}
                    </p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Upload Modal */}
      <UploadDocumentModalImproved
        isOpen={showUploadModal}
        onClose={() => setShowUploadModal(false)}
        onSuccess={handleUploadSuccess}
        clientId={selectedClient}
        currentFolderId={currentFolderId}
        currentPath={currentPath}
      />
    </div>
  );
};

export default DocumentManager;
